"use client";

import * as React from "react";
import { Composer } from "../composer/composer.js";
import { Message } from "../message/message.js";
import { MessageList } from "../message-list/message-list.js";
import { Shimmer } from "../shimmer/shimmer.js";
import { Sources, type SourceRef } from "../sources/sources.js";
import { cn } from "../../lib/utils.js";

// Local ambient — bundlers (Next, Vite, tsup) replace `process.env.NODE_ENV`
// at build time. Avoids pulling @types/node into the components package just
// for the controlled-mode dev-warning. Same pattern as slider.tsx.
declare const process: { env?: { NODE_ENV?: string } } | undefined;

/**
 * Speaker of a message. Mirrors the canonical `Role` union from
 * `@hex-core/components` exactly — kept inline (rather than imported
 * from `../types.js`) so the registry CLI distribution path (`npx hex
 * add conversation`) ships a self-contained file. Same precedent as
 * `task.tsx`'s inlined `ToolCallState`. The build-registry script
 * doesn't bundle `types.ts`, so importing from it would leave consumer
 * TS strict-mode unable to resolve the type at the install location.
 */
type Role = "user" | "assistant" | "system" | "tool";

/**
 * High-level chat shell. Composes `<MessageList>` over `messages`, an
 * optional `<Sources>` panel beneath the latest assistant turn, an
 * optional `<Shimmer>` placeholder for the in-flight assistant response,
 * and a `<Composer>` row at the bottom.
 *
 * Presentational: the consumer owns the `messages` array and the
 * `onSubmit` handler. The composer's text state is internal by default
 * so simple consumers don't thread input plumbing; pass `value` +
 * `onValueChange` together to take full control (suggested-prompt
 * injection, voice transcription, form-library integration).
 *
 * @example
 * <Conversation
 *   messages={messages}
 *   onSubmit={(text) => sendMessage(text)}
 *   isStreaming={isWaitingForFirstToken}
 *   sources={lastResponse.sources}
 *   placeholder="Ask anything…"
 * />
 */
export interface ConversationProps {
	/** Ordered chat history. Each item renders as one `<Message>`. */
	messages: ConversationMessage[];
	/** Called with the trimmed text when the user submits the composer. */
	onSubmit: (text: string) => void;
	/** Composer placeholder. */
	placeholder?: string;
	/** Controlled composer text. Pass with `onValueChange` to take control of the input — useful for suggested prompts, voice transcripts, or form-library integration. */
	value?: string;
	/** Called whenever the composer text changes. Required when `value` is set. */
	onValueChange?: (value: string) => void;
	/** When true, render a `<Shimmer>` placeholder above the composer (use during the dead time before the first stream token). */
	isStreaming?: boolean;
	/** Optional citations rendered as a `<Sources>` panel beneath the message stream. */
	sources?: SourceRef[];
	/** Disable the composer (e.g. while waiting on a tool call). */
	disabled?: boolean;
	/** Trailing slot inside the composer — typically a Send button. */
	composerActions?: React.ReactNode;
	className?: string;
}

/** A single message in a `<Conversation>`. */
export interface ConversationMessage {
	/** Stable identifier — used for the React key. */
	id: string;
	/** Speaker. */
	role: Role;
	/** Message content. Pass a string for plain text or a node (e.g. `<Markdown>`) for formatted output. */
	content: React.ReactNode;
}

/**
 * Render a chat conversation shell.
 * @param props - messages + submit handler + optional streaming/sources state
 * @returns A flex column with a scrolling message list, optional sources/shimmer, and a composer row
 */
function Conversation({
	messages,
	onSubmit,
	placeholder = "Ask anything…",
	value: valueProp,
	onValueChange: onValueChangeProp,
	isStreaming = false,
	sources,
	disabled = false,
	composerActions,
	className,
}: ConversationProps) {
	const [internalValue, setInternalValue] = React.useState("");
	const isControlled = valueProp !== undefined;
	const value = isControlled ? valueProp : internalValue;
	const setValue = isControlled
		? (next: string) => onValueChangeProp?.(next)
		: setInternalValue;

	if (
		typeof process !== "undefined" &&
		process.env?.NODE_ENV !== "production" &&
		isControlled &&
		typeof onValueChangeProp !== "function"
	) {
		// Surface the controlled-mode contract at runtime — `value` without
		// `onValueChange` makes the textarea silently read-only, which is a
		// frustrating debug. Schema commonMistakes flags it too, but a console
		// nudge catches it in the dev loop.
		console.warn(
			"<Conversation>: `value` was passed without `onValueChange`. The composer will be read-only — pass both props together for controlled mode, or omit both to let the component manage state internally.",
		);
	}

	function handleSubmit(text: string) {
		onSubmit(text);
		setValue("");
	}

	return (
		<div className={cn("flex h-full min-h-0 flex-col gap-3", className)}>
			<MessageList className="min-h-0 flex-1">
				{messages.map((m) => (
					<Message key={m.id} role={m.role}>
						{m.content}
					</Message>
				))}
				{isStreaming ? (
					<Message role="assistant">
						<Shimmer width="60%" />
					</Message>
				) : null}
			</MessageList>
			{sources && sources.length > 0 ? <Sources sources={sources} /> : null}
			<Composer
				value={value}
				onValueChange={setValue}
				onSubmit={handleSubmit}
				disabled={disabled}
				placeholder={placeholder}
			>
				{composerActions}
			</Composer>
		</div>
	);
}

export { Conversation };

"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Multi-line text input + submission shell for chat composers. Headless on
 * data flow — `value`/`onValueChange` are required so the consumer keeps
 * input state wherever fits (a `useChat` hook, a parent form, local state).
 *
 * Submits on Enter (without Shift). Children render after the textarea —
 * the canonical place for attachment buttons + a send button.
 *
 * Spreads remaining props onto the underlying `<form>`, so consumers can
 * pass `aria-label`, `id`, `name`, `data-*`, and similar attributes.
 *
 * @example
 * <Composer
 *   value={input}
 *   onValueChange={setInput}
 *   onSubmit={(v) => sendMessage(v)}
 *   placeholder="Ask anything…"
 * >
 *   <Button type="submit">Send</Button>
 * </Composer>
 */
export interface ComposerProps
	extends Omit<React.FormHTMLAttributes<HTMLFormElement>, "onSubmit" | "children"> {
	value: string;
	onValueChange: (value: string) => void;
	onSubmit: (value: string) => void;
	disabled?: boolean;
	placeholder?: string;
	/** Submit on Enter without Shift. Default true. */
	submitOnEnter?: boolean;
	/** Accessible name for the textarea. Defaults to `placeholder` when set, else "Message". */
	textareaAriaLabel?: string;
	/** Trailing slot — attachment buttons, send button, etc. */
	children?: React.ReactNode;
}

/**
 * Renders a chat composer with a textarea + slot for action buttons.
 * @param props - controlled value/handlers + slot children
 * @returns A form element with a textarea and trailing slot
 */
function Composer({
	value,
	onValueChange,
	onSubmit,
	disabled,
	placeholder,
	submitOnEnter = true,
	textareaAriaLabel,
	children,
	className,
	...rest
}: ComposerProps) {
	function trySubmit() {
		const trimmed = value.trim();
		if (!trimmed || disabled) return;
		onSubmit(trimmed);
	}

	function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
		if (!submitOnEnter) return;
		if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
			event.preventDefault();
			trySubmit();
		}
	}

	function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
		event.preventDefault();
		trySubmit();
	}

	return (
		<form
			{...rest}
			onSubmit={handleSubmit}
			className={cn(
				"flex items-end gap-2 rounded-lg border bg-background p-2",
				"focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2",
				"transition-all duration-[var(--duration-normal,200ms)] ease-out",
				className,
			)}
		>
			<textarea
				value={value}
				onChange={(event) => onValueChange(event.target.value)}
				onKeyDown={handleKeyDown}
				disabled={disabled}
				placeholder={placeholder}
				aria-label={textareaAriaLabel ?? placeholder ?? "Message"}
				rows={1}
				className={cn(
					"flex-1 resize-none bg-transparent px-2 py-1.5 text-sm leading-6",
					"placeholder:text-muted-foreground focus:outline-none",
					"disabled:cursor-not-allowed disabled:opacity-50",
					"max-h-48 min-h-[2.25rem] overflow-y-auto",
				)}
			/>
			{children}
		</form>
	);
}

export { Composer };

import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";
import { cn } from "../../lib/utils.js";
import type { Role } from "../types.js";

const messageVariants = cva(
	[
		"flex w-full gap-3 px-4 py-3 text-sm",
		"transition-colors duration-[var(--duration-normal,200ms)] ease-out",
	].join(" "),
	{
		variants: {
			role: {
				user: "bg-secondary/40 text-foreground",
				assistant: "bg-card text-card-foreground",
				system: "bg-muted text-muted-foreground italic",
				tool: "bg-accent/15 text-accent-foreground border-l-2 border-accent",
			},
		},
		defaultVariants: {
			role: "assistant",
		},
	},
);

/**
 * Single chat message row. Renders content with role-specific styling and a
 * `data-role` attribute so consumers can target arbitrary roles via CSS.
 *
 * Headless: accepts any `children`. Pair with `Markdown` + `CodeBlock` for
 * assistant turns, with `ToolCall` for agent steps, or with plain strings.
 *
 * @example
 * <Message role="user">What's the weather?</Message>
 * @example
 * <Message role="assistant">
 *   <Markdown>{streamingText}</Markdown>
 *   <ToolCall name="getWeather" state="result" args={...} result={...} />
 * </Message>
 */
export interface MessageProps
	extends Omit<React.HTMLAttributes<HTMLDivElement>, "role">,
		VariantProps<typeof messageVariants> {
	/** Speaker — drives variant styling and the `data-role` attribute. */
	role: Role;
	children: React.ReactNode;
}

/**
 * Renders a chat-message row scoped to one speaker.
 * @param props - role + content
 * @returns A styled div tagged with `data-role={role}`
 */
function Message({ role, className, children, ...props }: MessageProps) {
	return (
		<div data-role={role} className={cn(messageVariants({ role }), className)} {...props}>
			{children}
		</div>
	);
}

export { Message, messageVariants };

"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Auto-scrolling viewport for a stream of chat messages. When `autoScroll`
 * is true (default), the container pins to the bottom whenever its content
 * changes — including during streaming token updates. Detects whether the
 * user has scrolled away from the bottom and pauses auto-scroll until they
 * scroll back, so reading earlier turns doesn't fight the stream.
 *
 * @example
 * <MessageList>
 *   {messages.map((m) => <Message key={m.id} role={m.role}>{m.content}</Message>)}
 * </MessageList>
 */
export interface MessageListProps extends React.HTMLAttributes<HTMLDivElement> {
	/** Auto-scroll to bottom on content change (when user is already near the bottom). Default: true. */
	autoScroll?: boolean;
	children: React.ReactNode;
}

const NEAR_BOTTOM_THRESHOLD_PX = 80;

/**
 * Renders the scrolling message viewport.
 * @param props - children + autoScroll toggle
 * @returns A scrollable div that auto-pins to bottom when streaming
 */
function MessageList({
	autoScroll = true,
	className,
	children,
	...props
}: MessageListProps) {
	const ref = React.useRef<HTMLDivElement>(null);
	const stickToBottomRef = React.useRef(true);

	React.useEffect(() => {
		const el = ref.current;
		if (!el || !autoScroll) return;
		if (stickToBottomRef.current) {
			el.scrollTop = el.scrollHeight;
		}
	}, [autoScroll, children]);

	function handleScroll(event: React.UIEvent<HTMLDivElement>) {
		const el = event.currentTarget;
		const distance = el.scrollHeight - el.scrollTop - el.clientHeight;
		stickToBottomRef.current = distance < NEAR_BOTTOM_THRESHOLD_PX;
		props.onScroll?.(event);
	}

	return (
		<div
			ref={ref}
			role="log"
			aria-live="polite"
			aria-relevant="additions"
			className={cn("flex flex-col overflow-y-auto", className)}
			{...props}
			onScroll={handleScroll}
		>
			{children}
		</div>
	);
}

export { MessageList };

"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Single-line streaming placeholder. Used during the dead-time between
 * a user submitting a prompt and the first stream token arriving — a
 * gradient sweep across a flat bar that signals "the model is thinking
 * but hasn't started speaking yet."
 *
 * Wider than `<Loading>` (which is a multi-row skeleton) and narrower
 * than `<Skeleton>` (which is a sized placeholder block); use Shimmer
 * for the conversation pane, Loading for whole-screen states, Skeleton
 * for arbitrary placeholder shapes.
 *
 * @example
 * {isStreaming && <Shimmer width="80%" />}
 */
export interface ShimmerProps {
	/** CSS width — accepts any width value (e.g. `"60%"`, `"24rem"`). Defaults to full width. */
	width?: string;
	/** Override the default 1.5rem height for taller streaming bars. */
	height?: string;
	/** Sweep duration in ms. Defaults to 1500. */
	durationMs?: number;
	/** Accessible label announced to screen readers. */
	label?: string;
	className?: string;
}

/**
 * Render a streaming placeholder bar.
 *
 * Uses Tailwind's `animate-pulse` for the loading effect — same
 * approach as `<Skeleton>` so consumers don't need extra global CSS or
 * keyframes. The `durationMs` prop scales the pulse cycle via a CSS
 * variable so the animation stays in pulse's vertical-opacity family
 * rather than introducing a custom sweep keyframe (which would
 * conflict with React 19's stricter style-tag handling).
 *
 * @param props - Optional sizing + duration + label overrides.
 * @returns A pulsing placeholder bar.
 */
function Shimmer({
	width = "100%",
	height = "1.5rem",
	durationMs = 1500,
	label = "Loading…",
	className,
}: ShimmerProps) {
	return (
		<div
			role="status"
			aria-label={label}
			aria-live="polite"
			className={cn(
				// `motion-safe:` gates the pulse on `prefers-reduced-motion: no-preference` —
				// users with reduce-motion get a static bar.
				"motion-safe:animate-pulse rounded-md border border-foreground/[0.06] bg-muted",
				className,
			)}
			style={{
				width,
				height,
				animationDuration: `${durationMs}ms`,
			}}
		/>
	);
}

export { Shimmer };

"use client";

import {
	Collapsible,
	CollapsibleContent,
	CollapsibleTrigger,
} from "../../components/collapsible/collapsible.js";
import * as React from "react";
import { cn, safeUrl } from "../../lib/utils.js";
import { Citation } from "../citation/citation.js";

/**
 * Bordered card listing 1–N citation chips for a RAG response.
 *
 * Header reads "N sources" and is a clickable Radix Collapsible trigger;
 * body renders one `<Citation>` per source (re-using the in-house chip).
 * Defaults to open so consumers don't have to expand to see what was
 * cited.
 *
 * @example
 * <Sources
 *   sources={[
 *     { title: "Auth research", url: "https://example.com/auth", page: 3 },
 *     { title: "OAuth 2.1 spec", url: "https://oauth.net/2.1" },
 *   ]}
 * />
 */
export interface SourcesProps {
	/** Citation rows. Each becomes a `<Citation>` chip. */
	sources: SourceRef[];
	/** Whether the list is expanded by default. */
	defaultOpen?: boolean;
	className?: string;
}

/** Per-source data passed to a Citation chip. */
export interface SourceRef {
	title: string;
	url?: string;
	page?: number;
	/** Optional 1-based index. Falls back to array position. Use to keep
	 * the inline `<InlineCitation>` index aligned with the panel row when
	 * the model emits non-1-based numbering. */
	index?: number;
}

/**
 * Render a sources panel for an LLM response. Returns null when the
 * sources array is empty — consumers don't get a "0 sources" empty
 * card; they just don't render the panel at all.
 *
 * @param props - The list of sources + open-state default.
 * @returns A Collapsible wrapping a Citation cluster, or null if empty.
 */
function Sources({ sources, defaultOpen = true, className }: SourcesProps) {
	if (sources.length === 0) return null;
	const count = sources.length;
	const headerLabel = count === 1 ? "1 source" : `${count} sources`;

	return (
		<Collapsible
			defaultOpen={defaultOpen}
			className={cn(
				"overflow-hidden rounded-md border border-border bg-card text-card-foreground",
				className,
			)}
		>
			<CollapsibleTrigger
				className={cn(
					"group flex w-full items-center gap-2 px-3 py-1.5 text-left text-xs text-muted-foreground",
					"transition-all duration-[var(--duration-normal,200ms)] ease-out",
					"hover:text-foreground",
					"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
				)}
			>
				<DocStackGlyph />
				<span className="font-medium">{headerLabel}</span>
				<Chevron />
			</CollapsibleTrigger>
			<CollapsibleContent className="overflow-hidden border-t border-foreground/[0.06]">
				<div className="flex flex-wrap items-center gap-1.5 p-2">
					{sources.map((s, i) => (
						<Citation
							key={`${s.url ?? s.title}-${i}`}
							title={s.title}
							// Gate the URL even though markdown-path callers already
							// route through `safeUrl` — direct-JSX consumers can hand
							// us anything.
							url={safeUrl(s.url)}
							page={s.page}
							index={s.index ?? i + 1}
						/>
					))}
				</div>
			</CollapsibleContent>
		</Collapsible>
	);
}

function DocStackGlyph() {
	return (
		<svg
			aria-hidden
			viewBox="0 0 16 16"
			width="12"
			height="12"
			fill="none"
			stroke="currentColor"
			strokeWidth="1.5"
			strokeLinecap="round"
			strokeLinejoin="round"
			className="shrink-0"
		>
			<path d="M5 3h7l1.5 1.5V13H5V3z" />
			<path d="M3 5v8.5L4.5 15H11" />
		</svg>
	);
}

function Chevron() {
	return (
		<svg
			aria-hidden
			viewBox="0 0 16 16"
			width="12"
			height="12"
			fill="none"
			stroke="currentColor"
			strokeWidth="1.5"
			strokeLinecap="round"
			strokeLinejoin="round"
			className="ml-auto shrink-0 transition-transform duration-200 group-data-[state=open]:rotate-180"
		>
			<path d="M4 6l4 4 4-4" />
		</svg>
	);
}

export { Sources };

/**
 * Shared type primitives for the `ai` component category. Kept SDK-agnostic
 * so a single `MessageProps`/`ToolCallProps` shape adapts to AI SDK
 * (`UIMessage.parts`), LangChain (`BaseMessage`), Mastra agent outputs, and
 * any custom backend with a thin caller-side mapping function.
 */

/** Speaker of a message. Matches AI SDK + LangChain role conventions. */
export type Role = "user" | "assistant" | "system" | "tool";

/**
 * Lifecycle of a tool/function invocation, surfaced as the `state` prop on
 * `ToolCall`. `pending` = queued, `running` = executing, `result` = returned
 * a value, `error` = threw. Picked to align with AI SDK v5 `tool-*` parts.
 */
export type ToolCallState = "pending" | "running" | "result" | "error";

"use client";

import * as CollapsiblePrimitive from "@radix-ui/react-collapsible";

/** Root container controlling the expanded state of the content. */
const Collapsible = CollapsiblePrimitive.Root;

/** The element that toggles the Collapsible open/closed. */
const CollapsibleTrigger = CollapsiblePrimitive.CollapsibleTrigger;

/** The collapsible content shown/hidden by the trigger. */
const CollapsibleContent = CollapsiblePrimitive.CollapsibleContent;

export { Collapsible, CollapsibleTrigger, CollapsibleContent };

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Source attribution chip — renders a citation for a RAG hit, search
 * result, or any external reference the assistant pulled from. Becomes a
 * clickable anchor when `url` is provided; otherwise a static span.
 *
 * @example
 * <Citation title="auth-overview.md" url={src.url} page={3} />
 * @example
 * <Cluster gap="xs">
 *   {sources.map((s, i) => (
 *     <Citation key={s.id} title={s.title} url={s.url} index={i + 1} />
 *   ))}
 * </Cluster>
 */
export interface CitationProps {
	title: string;
	url?: string;
	page?: number;
	/** Numeric index for inline footnote-style display (e.g. "[1] auth.md"). */
	index?: number;
	className?: string;
	children?: React.ReactNode;
}

/**
 * Renders a source citation chip. Uses an `<a>` when `url` is set so the
 * chip is keyboard-focusable + opens in a new tab; falls back to a
 * non-interactive span otherwise.
 *
 * @param props - title + optional url, page, index
 * @returns An anchor or span styled as a chip
 */
function Citation({ title, url, page, index, className, children }: CitationProps) {
	const baseClasses = cn(
		"inline-flex items-center gap-1.5 rounded-md border border-foreground/15 bg-card px-2 py-0.5 text-xs",
		"transition-all duration-[var(--duration-normal,200ms)] ease-out",
		className,
	);

	const body = (
		<>
			{typeof index === "number" ? (
				<span className="font-mono text-[10px] font-semibold text-muted-foreground">[{index}]</span>
			) : (
				<DocGlyph />
			)}
			<span className="truncate text-foreground">{title}</span>
			{typeof page === "number" ? (
				<span className="text-muted-foreground">p.{page}</span>
			) : null}
			{children}
		</>
	);

	if (url) {
		return (
			<a
				href={url}
				target="_blank"
				rel="noreferrer noopener"
				className={cn(
					baseClasses,
					"hover:border-foreground/30 hover:bg-secondary/40 hover:shadow-sm",
					"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
				)}
			>
				{body}
			</a>
		);
	}

	return <span className={baseClasses}>{body}</span>;
}

function DocGlyph() {
	return (
		<svg
			aria-hidden
			viewBox="0 0 16 16"
			width="11"
			height="11"
			fill="none"
			stroke="currentColor"
			strokeWidth="1.5"
			strokeLinecap="round"
			strokeLinejoin="round"
			className="shrink-0 text-muted-foreground"
		>
			<path d="M9 1.5H4.5A1.5 1.5 0 0 0 3 3v10a1.5 1.5 0 0 0 1.5 1.5h7A1.5 1.5 0 0 0 13 13V5.5L9 1.5z" />
			<path d="M9 1.5V5.5h4" />
		</svg>
	);
}

export { Citation };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}

